mapper.select:
SELECT cl.id, cl.consumable_id AS "consumableId", cl.lot_no AS "lotNo", cl.barcode, cl.quantity, cl.remaining, cl.location_id AS "locationId", cl.device_id AS "deviceId", cl.expire_at AS "expireAt", cl.status, cl.received_at AS "receivedAt", c.code AS "consumableCode", c.name AS "consumableName", dev.code AS "deviceCode", dev.name AS "deviceName", pos.code AS "positionCode" FROM consumable_lot cl JOIN consumable c ON c.id = cl.consumable_id AND c.tenant_id = cl.tenant_id LEFT JOIN resource_node dev ON dev.id = cl.device_id AND dev.tenant_id = cl.tenant_id LEFT JOIN resource_node pos ON pos.id = cl.location_id AND pos.tenant_id = cl.tenant_id WHERE cl.tenant_id = #{t} AND cl.deleted_at IS NULL
AND cl.consumable_id = #{consumableId}
AND dev.parent_id = #{islandId}
ORDER BY cl.id

mapper.update:
UPDATE position_state
   SET content_kind = NULL, content_id = NULL, updated_at = now()
 WHERE tenant_id = #{t} AND resource_id = #{resourceId}

mapper.select:
SELECT rl.id, rl.reagent_id AS "reagentId", rl.lot_no AS "lotNo", rl.volume, rl.remaining, rl.location_id AS "locationId", rl.device_id AS "deviceId", rl.expire_at AS "expireAt", rl.status, r.code AS "reagentCode", r.name AS "reagentName", dev.code AS "deviceCode", pos.code AS "positionCode" FROM reagent_lot rl JOIN reagent r ON r.id = rl.reagent_id AND r.tenant_id = rl.tenant_id LEFT JOIN resource_node dev ON dev.id = rl.device_id AND dev.tenant_id = rl.tenant_id LEFT JOIN resource_node pos ON pos.id = rl.location_id AND pos.tenant_id = rl.tenant_id WHERE rl.tenant_id = #{t} AND rl.deleted_at IS NULL
AND rl.reagent_id = #{reagentId}
AND dev.parent_id = #{islandId}
ORDER BY rl.id
